from manim import *
import math


def _smart_text(text, font_size):
    """含非 ASCII 字符（中文/希腊字母/全角符号）用 Text（Pango 渲染，支持中文）；纯 ASCII 用 MathTex（LaTeX 渲染，支持数学公式）。"""
    return Text(text, font_size=font_size) if any(ord(c) > 127 for c in text) else MathTex(text, font_size=font_size)


class Surface3DScene(ThreeDScene):
    def construct(self):
        expr = {{expr}}
        xr = {{x_range}}
        yr = {{y_range}}
        title_text = {{title}}

        self.set_camera_orientation(phi=70 * DEGREES, theta=-45 * DEGREES)

        axes = ThreeDAxes(
            x_range=xr,
            y_range=yr,
            z_range=[-2, 2, 1],
            axis_config={"include_numbers": True, "font_size": 14},
        )
        self.play(Create(axes))

        surface = Surface(
            lambda u, v: axes.c2p(u, v, eval(expr, {"__builtins__": {}}, {"x": u, "y": v, "np": np, "math": math})),
            u_range=xr,
            v_range=yr,
            resolution=(32, 32),
            fill_opacity=0.8,
            checkerboard_colors=[BLUE_D, BLUE_B],
        )
        self.play(Create(surface), run_time=3)

        if title_text:
            title = _smart_text(title_text, font_size=48).to_edge(UP)
            self.play(Write(title))

        self.wait(2)
